package org.brightstats.desktop;
import java.util.*;
import java.util.function.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.model.*;
import org.brightstats.model.ElementType.Family;

final class ModelLibraryDialog {
    private final Dialog<Void> dialog=new Dialog<>();private final ListView<ModelLibrary.Entry> list=new ListView<>();private final Label status=new Label();private final ComboBox<Family> family=new ComboBox<>();private final Supplier<ModelLibrary> current;private final Consumer<ModelLibrary> changed;private final Function<Family,TypedDiagram.Document> document;private final Predicate<ModelLibrary.Entry> activate;
    private final Button save=UiAppearance.button("Save new snapshot"),open=UiAppearance.button("Activate snapshot"),rename=UiAppearance.button("Rename"),duplicate=UiAppearance.button("Duplicate"),remove=UiAppearance.button("Remove snapshot");private BiFunction<String,String,Optional<String>> names=this::name;private BooleanSupplier confirmRemove=this::confirm;
    private ModelLibraryDialog(Window owner,Supplier<ModelLibrary> current,Consumer<ModelLibrary> changed,Function<Family,TypedDiagram.Document> document,Predicate<ModelLibrary.Entry> activate){this.current=current;this.changed=changed;this.document=document;this.activate=activate;dialog.initOwner(owner);dialog.setTitle("Named models");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);list.setPrefSize(470,330);list.setCellFactory(control->new ListCell<>(){@Override protected void updateItem(ModelLibrary.Entry entry,boolean empty){super.updateItem(entry,empty);setText(empty||entry==null?null:entry.name()+"  ["+entry.document().family()+"]");}});family.getItems().setAll(Family.values());family.setValue(Family.PLS);var commands=new FlowPane(8,8,family,save,open,rename,duplicate,remove);Label note=UiAppearance.label("Snapshots retain model settings and column bindings while sharing this project's dataset. Activating a snapshot makes it available in its family editor; calculations start only when you choose to run them.");note.setWrapText(true);status.setWrapText(true);VBox content=new VBox(10,list,commands,note,status);content.setPadding(new Insets(12));dialog.getDialogPane().setContent(content);
        save.setOnAction(event->guard(()->{var label=names.apply("Save model snapshot",family.getValue()+" model");if(label.isEmpty())return;changed.accept(current.get().add(label.get(),document.apply(family.getValue())));refresh(current.get().entries().getLast().id());status.setText("Snapshot added. Save the project to retain it on disk.");}));open.setOnAction(event->guard(()->{if(activate.test(selected()))dialog.close();}));rename.setOnAction(event->guard(()->{var old=selected();var label=names.apply("Rename snapshot",old.name());if(label.isEmpty())return;changed.accept(current.get().rename(old.id(),label.get()));refresh(old.id());}));duplicate.setOnAction(event->guard(()->{var old=selected();var label=names.apply("Duplicate snapshot",old.name()+" copy");if(label.isEmpty())return;changed.accept(current.get().duplicate(old.id(),label.get()));refresh(current.get().entries().getLast().id());}));remove.setOnAction(event->guard(()->{if(!confirmRemove.getAsBoolean())return;changed.accept(current.get().remove(selected().id()));refresh("");status.setText("Snapshot removed from the current project. Other snapshots and the dataset are unchanged.");}));list.getSelectionModel().selectedItemProperty().addListener((observable,old,value)->buttons());list.setOnMouseClicked(event->{if(event.getClickCount()==2)open.fire();});refresh("");}
    private Optional<String> name(String title,String initial){TextInputDialog input=new TextInputDialog(initial);input.initOwner(dialog.getDialogPane().getScene().getWindow());input.setTitle(title);input.setHeaderText("Model snapshot name");return input.showAndWait();}
    private boolean confirm(){var alert=new Alert(Alert.AlertType.CONFIRMATION,"Remove this named snapshot from the current project?",ButtonType.YES,ButtonType.NO);alert.initOwner(dialog.getDialogPane().getScene().getWindow());return alert.showAndWait().orElse(ButtonType.NO)==ButtonType.YES;}
    private ModelLibrary.Entry selected(){var selected=list.getSelectionModel().getSelectedItem();if(selected==null)throw new IllegalArgumentException("Select a named model.");return selected;}
    private void refresh(String id){list.getItems().setAll(current.get().entries());list.getItems().stream().filter(entry->entry.id().equals(id)).findFirst().ifPresent(entry->list.getSelectionModel().select(entry));buttons();}
    private void buttons(){boolean empty=list.getSelectionModel().getSelectedItem()==null;open.setDisable(empty);rename.setDisable(empty);duplicate.setDisable(empty);remove.setDisable(empty);}
    private void guard(Runnable action){try{action.run();}catch(RuntimeException problem){status.setText(problem.getMessage()==null?problem.getClass().getSimpleName():problem.getMessage());}}
    static void show(Window owner,Supplier<ModelLibrary> current,Consumer<ModelLibrary> changed,Function<Family,TypedDiagram.Document> document,Predicate<ModelLibrary.Entry> activate){new ModelLibraryDialog(owner,current,changed,document,activate).dialog.showAndWait();}
    static ModelLibrary smoke(Window owner,TypedDiagram.Document document,java.nio.file.Path screenshot)throws Exception{var saved=new java.util.concurrent.atomic.AtomicReference<>(new ModelLibrary());var editor=new ModelLibraryDialog(owner,saved::get,saved::set,family->document,entry->true);editor.family.setValue(document.family());var choices=new ArrayDeque<>(List.of("GUI model","GUI renamed","GUI alternative"));editor.names=(title,initial)->Optional.of(choices.removeFirst());editor.confirmRemove=()->true;editor.dialog.show();editor.save.fire();editor.rename.fire();editor.duplicate.fire();if(saved.get().entries().size()!=2||!saved.get().entries().getFirst().name().equals("GUI renamed"))throw new AssertionError("Model library save/rename/duplicate failed");editor.remove.fire();if(saved.get().entries().size()!=1)throw new AssertionError("Model library removal failed");editor.dialog.getDialogPane().applyCss();editor.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(screenshot);GraphicExport.png(screenshot,editor.dialog.getDialogPane(),1);editor.dialog.close();return saved.get();}
}
